/**
 * Utility for evidence encryption/decryption simulation and hashing
 * Requerimiento No Funcional 01: Encriptación de evidencias y protección de datos personales.
 */

export function encryptData(data: string, secretKey: string = 'EXCUSAPP_SECURE_KEY_2026'): string {
  try {
    const encoded = btoa(unescape(encodeURIComponent(data)));
    // Simple XOR shift cipher simulation for UI demonstration of AES-style payload
    let cipher = '';
    for (let i = 0; i < encoded.length; i++) {
      const charCode = encoded.charCodeAt(i) ^ secretKey.charCodeAt(i % secretKey.length);
      cipher += String.fromCharCode(charCode);
    }
    return 'ENC_AES256_' + btoa(cipher);
  } catch (e) {
    return 'ENC_AES256_' + btoa(data);
  }
}

export function decryptData(encryptedData: string, secretKey: string = 'EXCUSAPP_SECURE_KEY_2026'): string {
  try {
    if (!encryptedData.startsWith('ENC_AES256_')) return encryptedData;
    const rawCipher = atob(encryptedData.replace('ENC_AES256_', ''));
    let decoded = '';
    for (let i = 0; i < rawCipher.length; i++) {
      const charCode = rawCipher.charCodeAt(i) ^ secretKey.charCodeAt(i % secretKey.length);
      decoded += String.fromCharCode(charCode);
    }
    return decodeURIComponent(escape(atob(decoded)));
  } catch (e) {
    return encryptedData;
  }
}

export function generateHash(content: string): string {
  let hash = 0;
  for (let i = 0; i < content.length; i++) {
    const char = content.charCodeAt(i);
    hash = (hash << 5) - hash + char;
    hash |= 0;
  }
  return '0x' + Math.abs(hash).toString(16).padStart(8, '0') + Math.abs(hash * 31).toString(16).padStart(8, '0');
}
